<script lang="ts" setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Alert as AAlert, Button as AButton, Card as ACard, Checkbox as ACheckbox, Col as ACol, Drawer as ADrawer, Form as AForm, FormItem as AFormItem, Input as AInput, InputNumber as AInputNumber, Popconfirm as APopconfirm, Row as ARow, Select as ASelect, Space as ASpace, Table as ATable, Tag as ATag, message } from 'ant-design-vue';
import { type PageResult, useServerPagination } from '#/utils/server-pagination';

type Center={id:string;code:string;name:string}; type Node={id:string;name:string;protocol:string;host:string;servicePort:number;enabled:boolean}; type Server={id:string;domain:string;listenPort:number}; type Upstream={id:string;name:string}; type Option={value:string;label:string}; type Action='PROXY'|'STATIC'|'RETURN';
type Location={id:string;path:string;methods:string[];contentTypes:string[];upstreamId?:string;headerLengthMin:number;headerLengthMax:number;bodyLengthMin:number;bodyLengthMax:number;proxyConnectTimeoutMs:number;proxyReadTimeoutMs:number;proxySendTimeoutMs:number;rateLimitEnabled:boolean;ratePerSecond:number;rateLimitBurst:number;rateLimitNodelay:boolean;dynamicDnsEnabled:boolean;dynamicDnsHost?:string;dynamicDnsPort?:number;action:Action;rootPath?:string;aliasPath?:string;returnStatus?:number;returnBody?:string;returnContentTypeMode:'REQUEST'|'CUSTOM';returnContentType?:string;responseHeaders:string[]};
const route=useRoute(),router=useRouter(), centers=ref<Center[]>([]),nodes=ref<Node[]>([]),servers=ref<Server[]>([]),upstreams=ref<Upstream[]>([]),rows=ref<Location[]>([]),methods=ref<Option[]>([]),contentTypes=ref<Option[]>([]),centerId=ref<string>(),serverId=ref<string>(),nodeId=ref<string>(),drawer=ref(false),editing=ref<string>(); const pager=useServerPagination();
const blank=()=>({path:'/',methods:['GET'],contentTypes:[],upstreamId:undefined as string|undefined,headerLengthMin:0,headerLengthMax:8192,bodyLengthMin:0,bodyLengthMax:1_048_576,proxyConnectTimeoutMs:5000,proxyReadTimeoutMs:60_000,proxySendTimeoutMs:60_000,rateLimitEnabled:false,ratePerSecond:10,rateLimitBurst:0,rateLimitNodelay:false,dynamicDnsEnabled:false,dynamicDnsHost:'',dynamicDnsPort:80,action:'PROXY' as Action,rootPath:'',aliasPath:'',returnStatus:200,returnBody:'',returnContentTypeMode:'CUSTOM' as 'REQUEST'|'CUSTOM',returnContentType:'application/json',responseHeaders:['X-Frame-Options: SAMEORIGIN','X-Content-Type-Options: nosniff']}); const form=ref(blank());
const currentCenter=computed(()=>centers.value.find(v=>v.id===centerId.value)); const currentServer=computed(()=>servers.value.find(v=>v.id===serverId.value)); const currentNode=computed(()=>nodes.value.find(v=>v.id===nodeId.value)); const upstreamOptions=computed(()=>upstreams.value.map(v=>({value:v.id,label:v.name}))); const upstreamName=(id?:string)=>upstreams.value.find(v=>v.id===id)?.name||'—';
const columns=[{dataIndex:'path',key:'path',title:'匹配路径'},{dataIndex:'methods',key:'methods',title:'请求方法'},{key:'actionType',title:'处理方式'},{key:'upstream',title:'目标'},{key:'action',title:'操作',width:150}];
async function request<T>(path:string,options?:RequestInit):Promise<T>{const response=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(options?.headers??{})}});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.detail||body.message||'请求失败')}return response.status===204?undefined as T:response.json() as Promise<T>}
async function loadPage(){if(!centerId.value||!serverId.value)return;rows.value=pager.apply(await request<PageResult<Location>>(`/centers/${centerId.value}/http/servers/${serverId.value}/locations/paged?${pager.query()}`))}
async function loadCenter(id:string){centerId.value=id;serverId.value=undefined;nodeId.value=undefined;pager.reset();const values=await Promise.all([request<Node[]>(`/centers/${id}/nodes`),request<Server[]>(`/centers/${id}/http/servers`),request<Upstream[]>(`/centers/${id}/http/upstreams`)]);[nodes.value,servers.value,upstreams.value]=values;nodeId.value=nodes.value.find(v=>v.enabled)?.id||nodes.value[0]?.id; const requested=String(route.query.serverId||'');serverId.value=servers.value.some(v=>v.id===requested)?requested:servers.value[0]?.id;await loadPage()}
async function load(){try{const [allCenters,methodValues,typeValues]=await Promise.all([request<Center[]>('/centers'),request<Option[]>('/dictionaries/HTTP_METHOD'),request<Option[]>('/dictionaries/HTTP_CONTENT_TYPE')]);centers.value=allCenters;methods.value=methodValues.map(v=>({...v,label:`${v.label}（${v.value}）`}));contentTypes.value=typeValues.map(v=>({...v,label:`${v.label}（${v.value}）`}));const requested=String(route.query.centerId||'');await loadCenter(centers.value.some(v=>v.id===requested)?requested:centers.value[0]?.id||'');nodeId.value=String(route.query.nodeId||nodeId.value||'')}catch(e){message.error(e instanceof Error?e.message:'加载 Location 配置失败')}}
async function changeServer(id:string){serverId.value=id;pager.reset();await loadPage()}
function open(value?:Location){editing.value=value?.id;form.value=value?{...blank(),...value,responseHeaders:value.responseHeaders||[]}:blank();drawer.value=true}
async function save(){if(!centerId.value||!serverId.value||(form.value.action==='PROXY'&&!form.value.upstreamId))return;try{const {action,rootPath,aliasPath,returnStatus,returnBody,returnContentTypeMode,returnContentType,responseHeaders,...payload}=form.value;const saved=await request<Location>(`/centers/${centerId.value}/http/servers/${serverId.value}/locations${editing.value?`/${editing.value}`:''}`,{method:editing.value?'PUT':'POST',body:JSON.stringify(payload)});await request(`/centers/${centerId.value}/http/servers/${serverId.value}/locations/${saved.id}/directives`,{method:'PUT',body:JSON.stringify({action,rootPath,aliasPath,returnStatus,returnBody,returnContentTypeMode,returnContentType,responseHeaders})});drawer.value=false;await loadPage();message.success(editing.value?'Location 已更新':'Location 已创建')}catch(e){message.error(e instanceof Error?e.message:'保存 Location 失败')}}
async function remove(id:string){if(!centerId.value||!serverId.value)return;try{await request(`/centers/${centerId.value}/http/servers/${serverId.value}/locations/${id}`,{method:'DELETE'});await loadPage();message.success('Location 已删除')}catch(e){message.error(e instanceof Error?e.message:'删除 Location 失败')}}
onMounted(load);
</script>
<template><div class="ops-page"><a-card :bordered="false" title="Location 配置"><template #extra><a-button @click="router.push('/openresty/http-config')">返回 HTTP 配置</a-button></template><a-form layout="inline"><a-form-item label="中心"><a-select v-model:value="centerId" class="w-64" :options="centers.map(v=>({value:v.id,label:`${v.name}（${v.code}）`}))" @change="loadCenter"/></a-form-item><a-form-item label="OpenResty 实例"><a-select v-model:value="nodeId" class="w-88" :options="nodes.map(v=>({value:v.id,label:`${v.name}（${v.host}:${v.servicePort}）`}))"/></a-form-item><a-form-item label="HTTP Server"><a-select v-model:value="serverId" class="w-72" :options="servers.map(v=>({value:v.id,label:`${v.domain}:${v.listenPort}`}))" @change="changeServer"/></a-form-item></a-form><a-alert class="mt-4" type="info" show-icon :message="`配置层级：${currentCenter?.name || '—'} → ${currentNode ? `${currentNode.name}（${currentNode.host}:${currentNode.servicePort}）` : '全部实例'} → HTTP → ${currentServer ? `${currentServer.domain}:${currentServer.listenPort}` : '请选择 Server'} → Location`" description="此处只维护当前 Server 下的路由；保存后由所属中心发布到全部启用实例。"/></a-card><a-card class="mt-5" :bordered="false" :title="currentServer ? `${currentServer.domain}:${currentServer.listenPort} 的路由` : '路由列表'"><template #extra><a-button type="primary" :disabled="!serverId" @click="open()">新增 Location</a-button></template><a-table :columns="columns" :data-source="rows" :pagination="pager.table.value" row-key="id" @change="(p:any)=>{pager.change(p);loadPage()}"><template #bodyCell="{column,record}"><template v-if="column.key==='methods'"><a-tag v-for="m in record.methods" :key="m">{{m}}</a-tag></template><template v-else-if="column.key==='actionType'"><a-tag :color="record.action==='PROXY'?'blue':record.action==='STATIC'?'green':'orange'">{{record.action==='PROXY'?'代理转发':record.action==='STATIC'?'静态文件':'直接返回'}}</a-tag></template><template v-else-if="column.key==='upstream'">{{record.action==='PROXY'?upstreamName(record.upstreamId):record.action==='STATIC'?(record.aliasPath||record.rootPath):`HTTP ${record.returnStatus}`}}</template><template v-else-if="column.key==='action'"><a-space :size="0"><a-button type="link" @click="open(record)">编辑</a-button><a-popconfirm title="确认删除该 Location？" @confirm="remove(record.id)"><a-button danger type="link">删除</a-button></a-popconfirm></a-space></template></template></a-table></a-card><a-drawer v-model:open="drawer" :title="editing?'编辑 Location':'新增 Location'" :width="720" destroy-on-close><a-alert class="mb-4" type="info" show-icon message="支持代理、静态文件和直接返回；安全响应头将自动带 always。"/><a-form layout="vertical"><a-row :gutter="16"><a-col :span="12"><a-form-item label="匹配路径" required><a-input v-model:value="form.path"/></a-form-item></a-col><a-col :span="12"><a-form-item label="处理方式"><a-select v-model:value="form.action" :options="[{value:'PROXY',label:'代理转发（PROXY）'},{value:'STATIC',label:'静态文件（STATIC）'},{value:'RETURN',label:'直接返回（RETURN）'}]"/></a-form-item></a-col></a-row><a-form-item v-if="form.action==='PROXY'" label="转发 Upstream" required><a-select v-model:value="form.upstreamId" :options="upstreamOptions"/></a-form-item><a-row v-if="form.action==='STATIC'" :gutter="16"><a-col :span="12"><a-form-item label="root 目录"><a-input v-model:value="form.rootPath" placeholder="/srv/openresty-content/site-a"/></a-form-item></a-col><a-col :span="12"><a-form-item label="alias 目录"><a-input v-model:value="form.aliasPath" placeholder="与 root 二选一"/></a-form-item></a-col></a-row><a-row v-if="form.action==='RETURN'" :gutter="16"><a-col :span="6"><a-form-item label="状态码"><a-input-number v-model:value="form.returnStatus" :min="100" :max="599" class="w-full"/></a-form-item></a-col><a-col :span="9"><a-form-item label="Content-Type"><a-select v-model:value="form.returnContentTypeMode" :options="[{value:'CUSTOM',label:'自定义（CUSTOM）'},{value:'REQUEST',label:'跟随请求（REQUEST）'}]"/></a-form-item></a-col><a-col :span="9"><a-form-item v-if="form.returnContentTypeMode==='CUSTOM'" label="自定义类型"><a-input v-model:value="form.returnContentType"/></a-form-item></a-col></a-row><a-form-item v-if="form.action==='RETURN'" label="返回内容"><a-input v-model:value="form.returnBody"/></a-form-item><a-form-item label="请求方法"><a-select v-model:value="form.methods" mode="multiple" :options="methods"/></a-form-item><a-form-item label="Content-Type"><a-select v-model:value="form.contentTypes" mode="tags" :options="contentTypes" :token-separators="[',']" placeholder="留空表示不限制"/></a-form-item><a-form-item label="响应头与安全头"><a-select v-model:value="form.responseHeaders" mode="tags" :token-separators="[',']"/></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="请求头范围"><a-space><a-input-number v-model:value="form.headerLengthMin" :min="0"/><span>至</span><a-input-number v-model:value="form.headerLengthMax" :min="0"/></a-space></a-form-item></a-col><a-col :span="12"><a-form-item label="请求体范围"><a-space><a-input-number v-model:value="form.bodyLengthMin" :min="0"/><span>至</span><a-input-number v-model:value="form.bodyLengthMax" :min="0"/></a-space></a-form-item></a-col></a-row></a-form><template #footer><div class="flex justify-end gap-2"><a-button @click="drawer=false">取消</a-button><a-button type="primary" @click="save">保存</a-button></div></template></a-drawer></div></template>
